const result = $json.output ?? $json;

// Get all original dataset items
const sourceItems = $('Sample Feedback Dataset').all();

// Use the current item position to find the matching original message
const original = sourceItems[$itemIndex].json;

const originalMessage = original.feedback_text;

const allowedTopics = [
  'delivery_delay',
  'damaged_packaging',
  'print_quality',
  'adhesion',
  'artwork_process',
  'other',
  'positive',
  'neutral'
];

if (!allowedTopics.includes(result.topic)) {
  throw new Error(`Invalid topic: ${result.topic}`);
}

if (
  typeof result.evidence !== 'string' ||
  result.evidence.trim() === ''
) {
  throw new Error('Evidence cannot be empty.');
}

if (!originalMessage.includes(result.evidence)) {
  throw new Error(
    `Invalid evidence for ${original.feedback_id}: "${result.evidence}" was not found in the original message.`
  );
}

if (
  !Number.isInteger(result.severity) ||
  result.severity < 0 ||
  result.severity > 3
) {
  throw new Error('Severity must be an integer from 0 to 3.');
}

if (
  ['positive', 'neutral'].includes(result.topic) &&
  result.severity !== 0
) {
  throw new Error(
    'Positive and neutral feedback must have severity 0.'
  );
}

return {
  json: {
    feedback_id: original.feedback_id,
    product: original.product,
    source: original.source,
    date: original.date,

    topic: result.topic,
    severity: result.severity,
    evidence: result.evidence,
    requires_investigation: result.requires_investigation,

    evidence_valid: true,
    original_feedback: originalMessage,
    validated_at: new Date().toISOString()
  }
};

