const items = $input.all().map(item => item.json);

const complaintTopics = [
  'delivery_delay',
  'damaged_packaging',
  'print_quality',
  'adhesion',
  'artwork_process',
  'other'
];

const groups = {};
const productTotals = {};

// Count total feedback per product
for (const item of items) {
  const product = item.product;

  if (!productTotals[product]) {
    productTotals[product] = 0;
  }

  productTotals[product]++;
}

// Group feedback by product and topic
for (const item of items) {
  const key = `${item.product}::${item.topic}`;

  if (!groups[key]) {
    groups[key] = {
      product: item.product,
      topic: item.topic,
      total_messages: 0,
      highest_severity: 0,
      feedback_ids: [],
      evidence: [],
      messages: [],
      is_issue: complaintTopics.includes(item.topic)
    };
  }

  const group = groups[key];

  group.total_messages++;
  group.highest_severity = Math.max(
    group.highest_severity,
    item.severity
  );

  group.feedback_ids.push(item.feedback_id);

  group.evidence.push({
    feedback_id: item.feedback_id,
    text: item.evidence
  });

  group.messages.push({
    feedback_id: item.feedback_id,
    date: item.date,
    source: item.source,
    original_feedback: item.original_feedback
  });
}

// Calculate percentages and priorities
const results = Object.values(groups).map(group => {
  const productTotal = productTotals[group.product];

  const percentageOfProductFeedback =
    (group.total_messages / productTotal) * 100;

  let priority = 'Low';

  if (
    group.is_issue &&
    (
      group.total_messages >= 3 ||
      group.highest_severity === 3
    )
  ) {
    priority = 'High';
  } else if (
    group.is_issue &&
    group.total_messages >= 2
  ) {
    priority = 'Medium';
  }

  return {
    ...group,
    product_total_messages: productTotal,
    percentage_of_product_feedback:
      Number(percentageOfProductFeedback.toFixed(1)),
    priority
  };
});

// Show recurring problems first
results.sort((a, b) => {
  if (a.is_issue !== b.is_issue) {
    return a.is_issue ? -1 : 1;
  }

  if (b.total_messages !== a.total_messages) {
    return b.total_messages - a.total_messages;
  }

  return b.highest_severity - a.highest_severity;
});

return [
  {
    json: {
      total_feedback_messages: items.length,
      product_totals: productTotals,
      all_feedback: items,
      groups: results,
      recurring_issue_groups: results.filter(
        group => group.is_issue && group.total_messages >= 2
      ),
      generated_at: new Date().toISOString()
    }
  }
];

const report = $json;
const feedback = report.all_feedback;

// These periods are adjacent:
// Previous: September 6–9
// Current: September 10–13
const previousStart = '2026-09-06';
const currentStart = '2026-09-10';
const endExclusive = '2026-09-14';

const previous = feedback.filter(item =>
  item.date >= previousStart &&
  item.date < currentStart
);

const current = feedback.filter(item =>
  item.date >= currentStart &&
  item.date < endExclusive
);

const comparisons = report.groups
  .filter(group => group.is_issue)
  .map(group => {
    const currentProductFeedback = current.filter(
      item => item.product === group.product
    );

    const previousProductFeedback = previous.filter(
      item => item.product === group.product
    );

    const previousIssueCount = previous.filter(
      item =>
        item.product === group.product &&
        item.topic === group.topic
    ).length;

    const currentIssueCount = current.filter(
      item =>
        item.product === group.product &&
        item.topic === group.topic
    ).length;

    const currentShare = currentProductFeedback.length
      ? currentIssueCount / currentProductFeedback.length
      : 0;

    const previousShare = previousProductFeedback.length
      ? previousIssueCount / previousProductFeedback.length
      : null;

    const changePercentagePoints =
      previousShare === null
        ? null
        : Number(((currentShare - previousShare) * 100).toFixed(1));

    return {
      product: group.product,
      topic: group.topic,

      current_issue_messages: currentIssueCount,
      current_product_messages: currentProductFeedback.length,
      current_share_percentage: Number(
        (currentShare * 100).toFixed(1)
      ),

      previous_issue_messages: previousIssueCount,
      previous_product_messages: previousProductFeedback.length,
      previous_share_percentage:
        previousShare === null
          ? null
          : Number((previousShare * 100).toFixed(1)),

      change_percentage_points: changePercentagePoints,

      comparison_status:
        previousShare === null
          ? 'no_previous_period_data'
          : changePercentagePoints > 0
            ? 'increasing'
            : changePercentagePoints < 0
              ? 'decreasing'
              : 'unchanged',

      note:
        previousShare === null
          ? 'No previous-period product feedback was supplied, so an increase cannot be claimed.'
          : 'Shares use uploaded feedback for this product, not total orders or defect rates.'
    };
  });

return {
  json: {
    periods: {
      previous_start: previousStart,
      current_start: currentStart,
      end_exclusive: endExclusive
    },

    previous_period_message_count: previous.length,
    current_period_message_count: current.length,

    findings: report.groups,
    comparisons
  }
};

const report = $json;

const actionPlaybook = {
  delivery_delay:
    'Compare reported delivery dates with carrier tracking and dispatch records. Confirm where delays occur before assigning a cause.',

  damaged_packaging:
    'Review the supporting reports, request packaging photos where appropriate, and compare packing methods with carrier handling records.',

  print_quality:
    'Compare the customer reports with approved artwork proofs and production quality checks.',

  adhesion:
    'Review the reported surface, application conditions, and product batch before deciding whether materials or instructions need changes.',

  artwork_process:
    'Review the proof conversation and instructions to identify which artwork steps customers found unclear.'
};

const findingsByKey = new Map(
  report.findings.map(finding => [
    `${finding.product}::${finding.topic}`,
    finding
  ])
);

const tasks = [];

for (const comparison of report.comparisons) {
  const key = `${comparison.product}::${comparison.topic}`;
  const finding = findingsByKey.get(key);

  if (!finding) {
    continue;
  }

  // Only create tasks for repeated current-period issues
  if (comparison.current_issue_messages < 2) {
    continue;
  }

  const change = comparison.change_percentage_points ?? 0;

  let priority = 'Low';

  if (
    finding.highest_severity === 3 ||
    comparison.current_issue_messages >= 3 ||
    change >= 10
  ) {
    priority = 'High';
  } else if (
    finding.highest_severity >= 2 ||
    comparison.current_issue_messages >= 2
  ) {
    priority = 'Medium';
  }

  const taskKey = `${comparison.product
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')}:${comparison.topic}`;

  tasks.push({
    task_key: taskKey,
    title: `Investigate ${comparison.topic.replaceAll('_', ' ')} for ${comparison.product}`,

    product: comparison.product,
    topic: comparison.topic,
    priority,
    status: 'open',

    reason:
      comparison.comparison_status === 'increasing'
        ? 'Recurring issue is increasing compared with the previous period.'
        : comparison.comparison_status === 'no_previous_period_data'
          ? 'Recurring issue detected, but no previous-period comparison is available.'
          : 'Recurring issue detected in the current period.',

    metrics: {
      current_issue_messages: comparison.current_issue_messages,
      current_product_messages: comparison.current_product_messages,
      current_share_percentage: comparison.current_share_percentage,
      previous_issue_messages: comparison.previous_issue_messages,
      previous_product_messages: comparison.previous_product_messages,
      previous_share_percentage: comparison.previous_share_percentage,
      change_percentage_points: comparison.change_percentage_points,
      comparison_status: comparison.comparison_status
    },

    supporting_evidence: finding.evidence,
    source_messages: finding.messages,

    recommended_action:
      actionPlaybook[comparison.topic] ??
      'Review the supporting customer feedback and determine the next investigation step.',

    created_at: new Date().toISOString()
  });
}

tasks.sort((a, b) => {
  const priorityOrder = {
    High: 1,
    Medium: 2,
    Low: 3
  };

  return priorityOrder[a.priority] - priorityOrder[b.priority];
});

return tasks.map(task => ({
  json: task
}));

const task = $json;

return {
  json: {
    task_key: task.task_key,
    title: task.title,
    product: task.product,
    topic: task.topic,
    priority: task.priority,
    status: task.status,
    reason: task.reason,

    metrics: JSON.stringify(task.metrics),
    supporting_evidence: JSON.stringify(task.supporting_evidence),
    source_messages: JSON.stringify(task.source_messages),

    recommended_action: task.recommended_action,
    created_at: task.created_at,
    updated_at: new Date().toISOString()
  }
};

const task = $json;

const change =
  task.metrics?.change_percentage_points ?? 0;

const currentMessages =
  task.metrics?.current_issue_messages ?? 0;

const urgent =
  task.priority === 'High' ||
  task.metrics?.severity === 3 ||
  change >= 10 ||
  currentMessages >= 3;

const reasons = [];

if (task.priority === 'High') {
  reasons.push('High priority');
}

if (task.metrics?.severity === 3) {
  reasons.push('Severity 3');
}

if (change >= 10) {
  reasons.push(`Issue increased by ${change} percentage points`);
}

if (currentMessages >= 3) {
  reasons.push(`${currentMessages} current-period messages`);
}

return {
  json: {
    ...task,
    urgent,
    urgent_reason: reasons.length
      ? reasons.join('; ')
      : 'Standard investigation priority',
    notification_status: urgent
      ? 'notification_required'
      : 'no_notification_required'
  }
};
